import csv
import json
import os

from pyscipopt import Model, quicksum

BASE = "/app"
DATA = os.path.join(BASE, "data")
SUB = os.path.join(BASE, "submissions")
os.makedirs(SUB, exist_ok=True)

# ---------------- Load data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    config = json.load(f)
FEAS_TOL = float(config.get("feasibility_tolerance", 1e-5))
INT_TOL = float(config.get("integer_tolerance", 1e-5))
W_SCALE = float(config.get("warranty_risk_cost_scale", 35.0))

lines = {}
with open(os.path.join(DATA, "assembly_lines.csv")) as f:
    for row in csv.DictReader(f):
        lid = row["line_id"].strip()
        lines[lid] = {
            "type": row["line_type"].strip(),
            "hours": float(row["available_hours"]),
            "vcp_h": float(row["variable_cost_per_hour"]),
        }

orders = {}
with open(os.path.join(DATA, "pack_orders.csv")) as f:
    for row in csv.DictReader(f):
        oid = row["order_id"].strip()
        orders[oid] = {
            "family": row["pack_family"].strip(),
            "chem": row["chemistry"].strip(),
            "req": int(row["requested_packs"]),
            "cpp": int(row["cells_per_pack"]),
            "min_soh": float(row["min_avg_soh"]),
            "min_saf": float(row["min_avg_safety_score"]),
            "rev": float(row["revenue_per_pack"]),
            "fill": float(row["minimum_fill_rate"]),
        }

lots = {}
with open(os.path.join(DATA, "cell_lots.csv")) as f:
    for row in csv.DictReader(f):
        kid = row["lot_id"].strip()
        lots[kid] = {
            "chem": row["chemistry"].strip(),
            "avail": int(row["available_cells"]),
            "soh": float(row["state_of_health"]),
            "saf": float(row["safety_score"]),
            "cost": float(row["cell_cost"]),
            "warr": float(row["warranty_factor"]),
        }

elig = {}
with open(os.path.join(DATA, "line_family_eligibility.csv")) as f:
    for row in csv.DictReader(f):
        key = (row["line_id"].strip(), row["pack_family"].strip())
        elig[key] = {
            "setup_hours": float(row["setup_hours"]),
            "setup_cost": float(row["setup_cost"]),
            "base_hpp": float(row["base_hours_per_pack"]),
        }

pairs = []
pair_set = set()
with open(os.path.join(DATA, "lot_order_compatibility.csv")) as f:
    for row in csv.DictReader(f):
        oid = row["order_id"].strip()
        kid = row["lot_id"].strip()
        p = {
            "max_packs": int(row["max_packs"]),
            "test": float(row["test_cost_per_pack"]),
            "hmult": float(row["hours_multiplier"]),
        }
        pairs.append((oid, kid, p))
        pair_set.add((oid, kid))

# ---------------- Build model ----------------
model = Model("battery_pack_assembly")
model.setParam("gaprel", 0.0005)

time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

y = {}
x = {}
obj_terms = []
obj_const = 0.0

# Setup variables: one per (line, order) where line is eligible for order's family
for oid, o in orders.items():
    fam = o["family"]
    for lid in lines:
        if (lid, fam) not in elig:
            continue
        y[(lid, oid)] = model.addVar(name=f"y_{lid}_{oid}", vtype="B", lb=0.0, ub=1.0, obj=0.0)

# Build variables: (line, order, lot) for eligible lines and approved pairings
for oid, kid, p in pairs:
    o = orders[oid]
    k = lots[kid]
    fam = o["family"]
    for lid in lines:
        if (lid, fam) not in elig:
            continue
        e = elig[(lid, fam)]
        # per-pack net coefficient (excluding line variable hours, which is also per pack)
        per_pack = (
            o["rev"]
            - o["cpp"] * k["cost"]
            - p["test"]
            - W_SCALE * k["warr"]
            - lines[lid]["vcp_h"] * e["base_hpp"] * p["hmult"]
        )
        ub = min(p["max_packs"], o["req"])
        v = model.addVar(name=f"x_{lid}_{oid}_{kid}", vtype="I", lb=0.0, ub=float(ub), obj=per_pack)
        x[(lid, oid, kid)] = v
        obj_terms.append(per_pack * v)

# Setup cost terms
for (lid, oid), v in y.items():
    fam = orders[oid]["family"]
    e = elig[(lid, fam)]
    obj_terms.append(-e["setup_cost"] * v)

model.setObjective(quicksum(obj_terms), sense="maximize")

# Constraints
# 1. Demand upper bound and 2. minimum fill
for oid, o in orders.items():
    fam = o["family"]
    idx = [(lid, oid, kid) for (lid, oid2, kid) in x if oid2 == oid and (lid, fam) in elig]
    total = quicksum([x[t] for t in idx])
    model.addCons(total <= o["req"], name=f"demand_ub_{oid}")
    min_fill = int(round(o["fill"] * o["req"]))
    min_fill = max(0, min(min_fill, o["req"]))
    model.addCons(total >= min_fill, name=f"minfill_{oid}")

# 3. Pairing cap (already in ub, but add explicit for clarity/safety)
for (oid, kid, p), (lid, oid2, kid2) in [((oid, kid, p), t) for t in x for (oid, kid, p) in [(t[1], t[2], None)] if False]:
    pass
for t, v in x.items():
    lid, oid, kid = t
    p = None
    for (o2, k2, pp) in pairs:
        if o2 == oid and k2 == kid:
            p = pp
            break
    if p is not None:
        model.addCons(v <= p["max_packs"], name=f"paircap_{lid}_{oid}_{kid}")

# 4. Lot cell availability
for kid, k in lots.items():
    terms = []
    for (lid, oid, kid2), v in x.items():
        if kid2 == kid:
            terms.append(orders[oid]["cpp"] * v)
    if terms:
        model.addCons(quicksum(terms) <= k["avail"], name=f"lotcap_{kid}")

# 5 & 6. Quality thresholds per order
for oid, o in orders.items():
    fam = o["family"]
    idx = [t for t in x if t[1] == oid]
    total = quicksum([x[t] for t in idx])
    soh_expr = quicksum([lots[t[2]]["soh"] * x[t] for t in idx])
    saf_expr = quicksum([lots[t[2]]["saf"] * x[t] for t in idx])
    model.addCons(soh_expr >= o["min_soh"] * total, name=f"soh_{oid}")
    model.addCons(saf_expr >= o["min_saf"] * total, name=f"saf_{oid}")

# 7. Line capacity
for lid, l in lines.items():
    lhs = []
    for (lid2, oid), v in y.items():
        if lid2 == lid:
            fam = orders[oid]["family"]
            lhs.append(elig[(lid, fam)]["setup_hours"] * v)
    for (lid2, oid, kid), v in x.items():
        if lid2 == lid:
            fam = orders[oid]["family"]
            e = elig[(lid, fam)]
            for (o2, k2, pp) in pairs:
                if o2 == oid and k2 == kid:
                    lhs.append(e["base_hpp"] * pp["hmult"] * v)
                    break
    model.addCons(quicksum(lhs) <= l["hours"], name=f"linecap_{lid}")

# 8. Linking: x <= D(o) * y
for (lid, oid, kid), v in x.items():
    fam = orders[oid]["family"]
    yv = y[(lid, oid)]
    model.addCons(v <= orders[oid]["req"] * yv, name=f"link_{lid}_{oid}_{kid}")

# ---------------- Solve ----------------
status = "unknown"
obj_val = None
sol = None
try:
    model.optimize()
    status = model.getStatus()
    if model.getNSols() > 0:
        sol = model.getBestSol()
        obj_val = model.getObjVal()
        print(f"Status: {status}, objective: {obj_val:.8f}, nsols: {model.getNSols()}")
    else:
        print(f"Status: {status}, no solution found")
except Exception as e:
    print(f"Solver error: {e}")
    status = "error"

# ---------------- Extract solution ----------------
y_sol = {}
x_sol = {}
if sol is not None:
    for (lid, oid), v in y.items():
        y_sol[(lid, oid)] = int(round(model.getVal(v)))
    for (lid, oid, kid), v in x.items():
        x_sol[(lid, oid, kid)] = int(round(model.getVal(v)))

# ---------------- Validate ----------------
errors = []
def check(cond, msg):
    if not cond:
        errors.append(msg)

# integrality / binary
for (lid, oid), val in y_sol.items():
    check(val in (0, 1), f"setup not binary: {lid},{oid}={val}")
for (lid, oid, kid), val in x_sol.items():
    check(val >= 0, f"build negative: {lid},{oid},{kid}={val}")

# demand & fill
for oid, o in orders.items():
    tot = sum(v for (l2, o2, k2), v in x_sol.items() if o2 == oid)
    check(tot <= o["req"] + INT_TOL, f"demand exceeded {oid}: {tot}")
    min_fill = int(round(o["fill"] * o["req"]))
    check(tot + INT_TOL >= min_fill, f"min fill violated {oid}: {tot} < {min_fill}")
    # pairing caps
    for (l2, o2, k2), v in x_sol.items():
        if o2 == oid:
            for (o3, k3, pp) in pairs:
                if o3 == oid and k3 == k2:
                    check(v <= pp["max_packs"] + INT_TOL, f"pair cap violated {oid},{k2}: {v}")
    # quality
    if tot > 0:
        soh_w = sum(lots[k2]["soh"] * v for (l2, o2, k2), v in x_sol.items() if o2 == oid)
        saf_w = sum(lots[k2]["saf"] * v for (l2, o2, k2), v in x_sol.items() if o2 == oid)
        check(soh_w / tot + FEAS_TOL >= o["min_soh"], f"soh violated {oid}: {soh_w/tot}")
        check(saf_w / tot + FEAS_TOL >= o["min_saf"], f"safety violated {oid}: {saf_w/tot}")

# lot availability
for kid, k in lots.items():
    used = sum(orders[o2]["cpp"] * v for (l2, o2, k2), v in x_sol.items() if k2 == kid)
    check(used <= k["avail"] + INT_TOL, f"lot cap violated {kid}: {used} > {k['avail']}")

# line capacity
for lid, l in lines.items():
    hrs = 0.0
    for (l2, oid), val in y_sol.items():
        if l2 == lid:
            fam = orders[oid]["family"]
            hrs += elig[(lid, fam)]["setup_hours"] * val
    for (l2, oid, kid), val in x_sol.items():
        if l2 == lid and val > 0:
            fam = orders[oid]["family"]
            e = elig[(lid, fam)]
            for (o2, k2, pp) in pairs:
                if o2 == oid and k2 == kid:
                    hrs += e["base_hpp"] * pp["hmult"] * val
                    break
    check(hrs <= l["hours"] + FEAS_TOL, f"line cap violated {lid}: {hrs} > {l['hours']}")

# linking
for (lid, oid, kid), val in x_sol.items():
    if val > 0:
        check(y_sol.get((lid, oid), 0) == 1, f"linking violated {lid},{oid},{kid}")

if errors:
    print("VALIDATION ERRORS:")
    for e in errors:
        print(" -", e)
else:
    print("All validation checks passed.")

# ---------------- Write solution ----------------
sol_path = os.path.join(SUB, "solution.csv")
with open(sol_path, "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["row_type", "line_id", "order_id", "lot_id", "value"])
    for (lid, oid), val in sorted(y_sol.items()):
        if val:
            w.writerow(["setup", lid, orders[oid]["family"], "", f"{val:.8f}"])
    for (lid, oid, kid), val in sorted(x_sol.items()):
        if val:
            w.writerow(["build", lid, oid, kid, f"{val:.8f}"])

print(f"Wrote {sol_path}")
print(f"Status: {status}")
if obj_val is not None:
    print(f"Objective (contribution margin): {obj_val:.8f}")

# Manual objective recomputation for the log
if x_sol or y_sol:
    total = 0.0
    for (lid, oid, kid), val in x_sol.items():
        o = orders[oid]
        k = lots[kid]
        fam = o["family"]
        e = elig[(lid, fam)]
        pp = None
        for (o2, k2, p2) in pairs:
            if o2 == oid and k2 == kid:
                pp = p2
                break
        total += val * (o["rev"] - o["cpp"] * k["cost"] - pp["test"] - W_SCALE * k["warr"] - lines[lid]["vcp_h"] * e["base_hpp"] * pp["hmult"])
    for (lid, oid), val in y_sol.items():
        if val:
            total -= elig[(lid, orders[oid]["family"])]["setup_cost"]
    print(f"Recomputed objective: {total:.8f}")

model.free()
